window.__DAILY_CHUNKS__[4] = [{"week":28,"level":"B1","theme":"教育与学习：表达观点与间接引语入门","days":[{"day":1,"theme":"词汇 · 教育与学习","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：教育与学习","body":"教育与学习（L'éducation et l'apprentissage）是这一周要反复见面的主题域。打开 vocab.html#t12，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"expliquer\">expliquer</span>（解释）、<span class=\"fr\" data-fr=\"déclarer\">déclarer</span>（声明）、<span class=\"fr\" data-fr=\"affirmer\">affirmer</span>（断言）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t12","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5005","level":"B1","skill":"vocab","prompt":"« une formation » 的意思是？","options":["培训","形式","信息"],"answer":"培训","explain":"formation 是培训、培养；forme 是形式；information 是信息。","source":"词汇 · 教育"},{"ref":"bank:vocab:A1:教育与学习"}]},{"type":"vocab","title":"搭配与辨析：un lycée / une formation","body":"<span class=\"fr\" data-fr=\"un lycée\">un lycée</span>（高中）与 <span class=\"fr\" data-fr=\"une formation\">une formation</span>（培训）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t12","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5006","level":"B1","skill":"vocab","prompt":"« un lycée » 的意思是？","options":["高中","初中","大学"],"answer":"高中","explain":"lycée 是高中；collège 是初中；université 是大学。","source":"词汇 · 教育"},{"ref":"bank:vocab:A1:教育与学习"}]},{"type":"listen","title":"听音辨词：教育与学习","body":"打开 对话页的 d20 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un diplôme\">un diplôme</span>（文凭）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d20","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Il dit qu'il est malade.\">Il dit qu'il est malade.</span>（他说他病了。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：教育与学习 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"expliquer\">expliquer</span> <span class=\"fr\" data-fr=\"déclarer\">déclarer</span> <span class=\"fr\" data-fr=\"affirmer\">affirmer</span> <span class=\"fr\" data-fr=\"un lycée\">un lycée</span> <span class=\"fr\" data-fr=\"une formation\">une formation</span> <span class=\"fr\" data-fr=\"un diplôme\">un diplôme</span>。说不出来的词立刻回到 vocab.html#t12 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t12","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:教育与学习"}]}]},{"day":2,"theme":"语法 · 直接引语转间接引语","type":"grammar","steps":[{"type":"grammar","title":"语法点：直接引语转间接引语","body":"【直接引语转间接引语】把直接引语转成间接引语要做四件事：改人称、调时态、换时间地点词、调整句型。主句是现在时时从句时态不变：Il dit qu'il est malade；主句是过去时时时态向后推移：现在时变未完成过去时、复合过去时变愈过去时、简单将来时变条件式。 例句：<span class=\"fr\" data-fr=\"Il dit qu'il est malade.\">Il dit qu'il est malade.</span>（他说他病了。）；<span class=\"fr\" data-fr=\"Elle a expliqué qu'elle avait déjà visité ce musée.\">Elle a expliqué qu'elle avait déjà visité ce musée.</span>（她解释说自己之前已经参观过这个博物馆。）。对照 grammar-b1b2.html#discours-indirect 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#discours-indirect","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5005","level":"B1","skill":"grammar","prompt":"« Il dit : “Je suis malade.” » 的转述是？","options":["Il dit qu'il est malade.","Il dit qu'il était malade.","Il dit que je suis malade."],"answer":"Il dit qu'il est malade.","explain":"主句是现在时，从句时态不变，只改人称：je 变 il。","source":"语法 · 间接引语"},{"ref":"bank:grammar:B1:间接引语"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#discours-indirect 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Il dit qu'il est malade.\">Il dit qu'il est malade.</span>（他说他病了。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#discours-indirect","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5006","level":"B1","skill":"grammar","prompt":"主句是过去时，从句的复合过去时要变成？","options":["愈过去时","保持原样","简单将来时"],"answer":"愈过去时","explain":"主句为过去时，从句时态向后推移：复合过去时变愈过去时。","source":"语法 · 时态推移"},{"ref":"bank:grammar:B1:间接引语"}]},{"type":"read","title":"在短文里找直接引语转间接引语","body":"在 grammar-b1b2.html#discours-indirect 的例句和章末小测里挑 5 句，圈出所有属于「直接引语转间接引语」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#discours-indirect","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Il dit qu'il est malade.\">Il dit qu'il est malade.</span>（他说他病了。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，直接引语转间接引语 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：四步转换法","body":"今天再回 grammar-b1b2.html#di-regle 看一遍 四步转换法，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#di-regle","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:间接引语"}]}]},{"day":3,"theme":"精听 · 对话页的 d20 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d20 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d20","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5003","level":"B1","skill":"listening","prompt":"听到 « Il a dit qu'il viendrait. » 中 viendrait 是？","options":["条件式，代替原来的将来时","简单将来时","未完成过去时"],"answer":"条件式，代替原来的将来时","explain":"主句过去时，从句原来的简单将来时要推移为条件式。","source":"语法 · 时态推移"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段访谈，用自己的话转述 8 句。","src":"dialogue.html#d20","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"expliquer\">expliquer</span>（解释）、<span class=\"fr\" data-fr=\"déclarer\">déclarer</span>（声明）、<span class=\"fr\" data-fr=\"affirmer\">affirmer</span>（断言）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t12","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:教育与学习"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「直接引语转间接引语 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d20","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 表达观点与间接引语入门","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：转述一条新闻（谁说了什么）2 分钟。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5002","level":"B1","skill":"speaking","prompt":"转述新闻时的第一步是？","options":["说清谁说的、什么时候说的","先评论再转述","直接背原句"],"answer":"说清谁说的、什么时候说的","explain":"转述先交代信息来源，再讲内容，避免把自己的判断混进去。","source":"口语 · 转述"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d20 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、直接引语转间接引语 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d20","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un lycée\">un lycée</span>（高中）、<span class=\"fr\" data-fr=\"une formation\">une formation</span>（培训）、<span class=\"fr\" data-fr=\"un diplôme\">un diplôme</span>（文凭）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t12 再看一遍例句。","src":"vocab.html#t12","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:教育与学习"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 表达观点与间接引语入门","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读一篇 600 词教育话题文章，标出作者论点与论据。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5003","level":"B1","skill":"reading","prompt":"« selon le rapport » 的意思是？","options":["根据报告","反对报告","报告之后"],"answer":"根据报告","explain":"selon 表示根据、按照，是转述信息来源的常用词。","source":"词汇 · 转述"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"expliquer\">expliquer</span>（解释）、<span class=\"fr\" data-fr=\"déclarer\">déclarer</span>（声明）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t12","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:教育与学习"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#discours-indirect，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#discours-indirect","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:间接引语"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「直接引语转间接引语」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 表达观点与间接引语入门","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 180 词文章摘要加 8 个转述句。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5002","level":"B1","skill":"writing","prompt":"转述时 « hier » 在间接引语中要变成？","options":["la veille","le lendemain","aujourd'hui"],"answer":"la veille","explain":"主句过去时时 hier 推移为 la veille；demain 才变 le lendemain。","source":"语法 · 时间词推移"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#discours-indirect，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#discours-indirect","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:间接引语"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「直接引语转间接引语」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"expliquer\">expliquer</span>（解释）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 表达观点与间接引语入门","type":"review","steps":[{"type":"review","title":"本周回顾：教育与学习：表达观点与间接引语入门","body":"这一周围绕「教育与学习：表达观点与间接引语入门」展开：语法主线是 直接引语转间接引语，词汇主线是 教育与学习。先用 3 句话口头复述本周学了什么，再打开日历页第 28 周清单逐条核对里程碑。","src":"calendar.html#wk-28","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:教育与学习"}]},{"type":"review","title":"语法复盘：直接引语转间接引语","body":"从 grammar-b1b2.html#discours-indirect 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#discours-indirect","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:间接引语"}]},{"type":"review","title":"词汇自测：教育与学习","body":"遮住中文看 vocab.html#t12 的 6 个核心词：<span class=\"fr\" data-fr=\"expliquer\">expliquer</span> <span class=\"fr\" data-fr=\"déclarer\">déclarer</span> <span class=\"fr\" data-fr=\"affirmer\">affirmer</span> <span class=\"fr\" data-fr=\"un lycée\">un lycée</span> <span class=\"fr\" data-fr=\"une formation\">une formation</span> <span class=\"fr\" data-fr=\"un diplôme\">un diplôme</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t12","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5007","level":"B1","skill":"vocab","prompt":"« affirmer » 的意思是？","options":["断言","否认","提问"],"answer":"断言","explain":"affirmer 是断言、肯定地说；nier 是否认；demander 是提问。","source":"词汇 · 转述动词"},{"id":"q-vocab-b1-5008","level":"B1","skill":"vocab","prompt":"« expliquer » 的意思是？","options":["解释","抱怨","重复"],"answer":"解释","explain":"expliquer 是解释；se plaindre 是抱怨；répéter 是重复。","source":"词汇 · 转述动词"},{"ref":"bank:vocab:A1:教育与学习"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d20","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5004","level":"B1","skill":"listening","prompt":"听到 « elle a expliqué qu'elle avait fini » 表示？","options":["她解释说自己之前已经做完了","她解释说自己将要完成","她解释说自己正在做"],"answer":"她解释说自己之前已经做完了","explain":"主句过去时，从句复合过去时推移为愈过去时。","source":"语法 · 时态推移"},{"id":"q-read-b1-5004","level":"B1","skill":"reading","prompt":"读教育类文章时，应该先找什么？","options":["论点与论据","生词表","作者生平"],"answer":"论点与论据","explain":"先抓论点与论据的结构，再处理词汇细节，效率更高。","source":"考试 · 阅读策略"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 直接引语转间接引语 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#discours-indirect 再核对一次。","src":"grammar-b1b2.html#di-regle","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5007","level":"B1","skill":"grammar","prompt":"« Elle demande si je viendrai. » 中 si 表示？","options":["一般疑问的转述","条件","因果"],"answer":"一般疑问的转述","explain":"转述一般疑问句用 si（是否），特殊疑问句则保留疑问词。","source":"语法 · 疑问转述"},{"id":"q-gram-b1-5008","level":"B1","skill":"grammar","prompt":"「他让我别迟到」应说？","options":["Il me dit de ne pas être en retard.","Il me dit ne pas être en retard.","Il me dit que ne pas être en retard."],"answer":"Il me dit de ne pas être en retard.","explain":"转述命令用 dire de 加不定式，否定式把 ne pas 放在不定式前。","source":"语法 · 命令转述"},{"ref":"bank:grammar:B1:间接引语"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":29,"level":"B1","theme":"虚拟式（一）：形式与意志、情感、必要","days":[{"day":1,"theme":"词汇 · 情感与态度","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：情感与态度","body":"本周词汇主战场是情感与态度（Les émotions et les attitudes）。先到 vocab.html#t18 把词表扫一遍，把 <span class=\"fr\" data-fr=\"il faut que\">il faut que</span>（必须……）、<span class=\"fr\" data-fr=\"vouloir que\">vouloir que</span>（希望……）、<span class=\"fr\" data-fr=\"être content que\">être content que</span>（高兴……）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t18","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5009","level":"B1","skill":"vocab","prompt":"« un souhait » 的意思是？","options":["愿望","签名","结果"],"answer":"愿望","explain":"souhait 是愿望；signature 是签名；résultat 是结果。","source":"词汇 · 情感"},{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"vocab","title":"搭配与辨析：douter que / une émotion","body":"把 <span class=\"fr\" data-fr=\"douter que\">douter que</span>（怀疑……）和 <span class=\"fr\" data-fr=\"une émotion\">une émotion</span>（情感）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t18","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5010","level":"B1","skill":"vocab","prompt":"« douter que » 后接什么语式？","options":["虚拟式","直陈式","条件式"],"answer":"虚拟式","explain":"douter que 表达怀疑，从句用虚拟式。","source":"语法 · 虚拟式触发词"},{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"listen","title":"听音辨词：情感与态度","body":"打开 对话页的 d30 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un souhait\">un souhait</span>（愿望）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d30","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Il faut que tu sois à l'heure.\">Il faut que tu sois à l'heure.</span>（你必须准时。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：情感与态度 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"il faut que\">il faut que</span> <span class=\"fr\" data-fr=\"vouloir que\">vouloir que</span> <span class=\"fr\" data-fr=\"être content que\">être content que</span> <span class=\"fr\" data-fr=\"douter que\">douter que</span> <span class=\"fr\" data-fr=\"une émotion\">une émotion</span> <span class=\"fr\" data-fr=\"un souhait\">un souhait</span>。说不出来的词立刻回到 vocab.html#t18 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t18","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]}]},{"day":2,"theme":"语法 · 虚拟式","type":"grammar","steps":[{"type":"grammar","title":"语法点：虚拟式","body":"【虚拟式】虚拟式现在时的构成是「ils 现在时去掉 -ent 再加 -e, -es, -e, -ions, -iez, -ent」；être、avoir、aller、faire、pouvoir、savoir、vouloir 是不规则形式。触发虚拟式的常见结构有 vouloir que、il faut que、je suis content que，它们表达意志、必要或情感。 例句：<span class=\"fr\" data-fr=\"Il faut que tu sois à l'heure.\">Il faut que tu sois à l'heure.</span>（你必须准时。）；<span class=\"fr\" data-fr=\"Je suis content que vous veniez.\">Je suis content que vous veniez.</span>（我很高兴你们能来。）。对照 grammar-b1b2.html#subjonctif 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#subjonctif","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5009","level":"B1","skill":"grammar","prompt":"« Il faut que tu ___ à l'heure. »（être）","options":["sois","es","seras"],"answer":"sois","explain":"il faut que 触发虚拟式，être 的 tu 形式是 sois。","source":"语法 · 虚拟式变位"},{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 虚拟式 的规则和两个例句，再打开 grammar-b1b2.html#subjonctif 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#subjonctif","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5010","level":"B1","skill":"grammar","prompt":"« Je suis content que vous ___ . »（venir）","options":["veniez","venez","viendrez"],"answer":"veniez","explain":"情感类结构后接虚拟式，vous 的 venir 虚拟式为 veniez。","source":"语法 · 虚拟式变位"},{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"read","title":"在短文里找虚拟式","body":"在 grammar-b1b2.html#subjonctif 的例句和章末小测里挑 5 句，圈出所有属于「虚拟式」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#subjonctif","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Il faut que tu sois à l'heure.\">Il faut que tu sois à l'heure.</span>（你必须准时。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，虚拟式 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：虚拟式现在时变位","body":"今天再回 grammar-b1b2.html#subj-formation 看一遍 虚拟式现在时变位，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#subj-formation","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]}]},{"day":3,"theme":"精听 · 对话页的 d30 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d30 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d30","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5005","level":"B1","skill":"listening","prompt":"听到 /il fo kə ty vjɛn/ 中 vjɛn 的形式是？","options":["虚拟式","现在时","将来时"],"answer":"虚拟式","explain":"il faut que 后面必须用虚拟式，venir 的形式是 vienne / viennes。","source":"语法 · 虚拟式"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听含虚拟式的对话，标出每个虚拟式动词的引导词。","src":"dialogue.html#d30","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"il faut que\">il faut que</span>（必须……）、<span class=\"fr\" data-fr=\"vouloir que\">vouloir que</span>（希望……）、<span class=\"fr\" data-fr=\"être content que\">être content que</span>（高兴……）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t18","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「虚拟式 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d30","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 形式与意志、情感、必要","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：用 il faut que / je veux que / je doute que 各说 4 句真实需求。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5003","level":"B1","skill":"speaking","prompt":"表达「我需要你帮我」应说？","options":["J'ai besoin que tu m'aides.","J'ai besoin que tu m'aides pas.","Je besoin que tu aides-moi."],"answer":"J'ai besoin que tu m'aides.","explain":"avoir besoin que 后接虚拟式；代词要放在动词前。","source":"语法 · 虚拟式触发词"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d30 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、虚拟式 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d30","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"douter que\">douter que</span>（怀疑……）、<span class=\"fr\" data-fr=\"une émotion\">une émotion</span>（情感）、<span class=\"fr\" data-fr=\"un souhait\">un souhait</span>（愿望）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t18 再看一遍例句。","src":"vocab.html#t18","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 形式与意志、情感、必要","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页虚拟式章节与常用引导短语表。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5005","level":"B1","skill":"reading","prompt":"« bien que » 后接什么语式？","options":["虚拟式","直陈式","不定式"],"answer":"虚拟式","explain":"bien que 是让步连词，必须接虚拟式；même si 才接直陈式。","source":"语法 · 虚拟式连词"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「虚拟式」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"il faut que\">il faut que</span>（必须……）、<span class=\"fr\" data-fr=\"vouloir que\">vouloir que</span>（希望……）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t18","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#subjonctif，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#subjonctif","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「虚拟式」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 形式与意志、情感、必要","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 15 句「我希望、我需要、我害怕……」的虚拟式句。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5003","level":"B1","skill":"writing","prompt":"「我希望你能来」正确写法是？","options":["Je veux que tu viennes.","Je veux que tu viens.","Je veux tu viennes."],"answer":"Je veux que tu viennes.","explain":"vouloir que 后接虚拟式，而且 que 不能省略。","source":"语法 · 虚拟式"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#subjonctif，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#subjonctif","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「虚拟式」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"il faut que\">il faut que</span>（必须……）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 形式与意志、情感、必要","type":"review","steps":[{"type":"review","title":"本周回顾：虚拟式（一）：形式与意志、情感、必要","body":"这一周围绕「虚拟式（一）：形式与意志、情感、必要」展开：语法主线是 虚拟式，词汇主线是 情感与态度。先用 3 句话口头复述本周学了什么，再打开日历页第 29 周清单逐条核对里程碑。","src":"calendar.html#wk-29","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"review","title":"语法复盘：虚拟式","body":"从 grammar-b1b2.html#subjonctif 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#subjonctif","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"review","title":"词汇自测：情感与态度","body":"遮住中文看 vocab.html#t18 的 6 个核心词：<span class=\"fr\" data-fr=\"il faut que\">il faut que</span> <span class=\"fr\" data-fr=\"vouloir que\">vouloir que</span> <span class=\"fr\" data-fr=\"être content que\">être content que</span> <span class=\"fr\" data-fr=\"douter que\">douter que</span> <span class=\"fr\" data-fr=\"une émotion\">une émotion</span> <span class=\"fr\" data-fr=\"un souhait\">un souhait</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t18","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5011","level":"B1","skill":"vocab","prompt":"« une émotion » 的意思是？","options":["情感","运动","动机"],"answer":"情感","explain":"émotion 是情感；mouvement 是运动；motivation 是动机。","source":"词汇 · 情感"},{"id":"q-vocab-b1-5012","level":"B1","skill":"vocab","prompt":"« avoir peur que » 后接？","options":["虚拟式","直陈式","简单将来时"],"answer":"虚拟式","explain":"表达恐惧等情感的结构后接虚拟式。","source":"语法 · 虚拟式触发词"},{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d30","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5006","level":"B1","skill":"listening","prompt":"听到 /il fo kə ʒə paʁt/ 时 partir 应采用什么形式？","options":["虚拟式 parte","现在时 pars","将来时 partirai"],"answer":"虚拟式 parte","explain":"il faut que 后必须用虚拟式，je 的 partir 虚拟式是 parte。","source":"语法 · 虚拟式"},{"id":"q-read-b1-5006","level":"B1","skill":"reading","prompt":"虚拟式现在时的构成基础是？","options":["ils 现在时去 -ent 再加词尾","不定式直接加词尾","过去分词加助动词"],"answer":"ils 现在时去 -ent 再加词尾","explain":"从 ils 的现在时形式去掉 -ent 得到词干，再加 -e, -es, -e, -ions, -iez, -ent。","source":"语法 · 虚拟式变位"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 虚拟式 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#subjonctif 再核对一次。","src":"grammar-b1b2.html#subj-formation","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5011","level":"B1","skill":"grammar","prompt":"« Je doute qu'il ___ la vérité. »（dire）","options":["dise","dit","dira"],"answer":"dise","explain":"douter que 触发虚拟式，dire 的虚拟式为 dise。","source":"语法 · 虚拟式变位"},{"id":"q-gram-b1-5012","level":"B1","skill":"grammar","prompt":"下列哪个结构不接虚拟式？","options":["espérer que","il faut que","bien que"],"answer":"espérer que","explain":"espérer que 用直陈式；il faut que 与 bien que 接虚拟式。","source":"语法 · 虚拟式触发词"},{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":30,"level":"B1","theme":"环境与生态：观点陈述与论述段写作","days":[{"day":1,"theme":"词汇 · 环境与生态","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：环境与生态","body":"环境与生态（L'environnement et l'écologie）是这一周要反复见面的主题域。打开 vocab.html#t20，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"l'environnement\">l'environnement</span>（环境）、<span class=\"fr\" data-fr=\"le recyclage\">le recyclage</span>（回收）、<span class=\"fr\" data-fr=\"un déchet\">un déchet</span>（垃圾）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t20","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5013","level":"B1","skill":"vocab","prompt":"« le recyclage » 的意思是？","options":["回收","垃圾","气候"],"answer":"回收","explain":"recyclage 是回收；déchet 是垃圾；climat 是气候。","source":"词汇 · 环境"},{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"vocab","title":"搭配与辨析：le climat / l'énergie","body":"<span class=\"fr\" data-fr=\"le climat\">le climat</span>（气候）与 <span class=\"fr\" data-fr=\"l'énergie\">l'énergie</span>（能源）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t20","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5014","level":"B1","skill":"vocab","prompt":"« réduire » 的意思是？","options":["减少","生产","回收"],"answer":"减少","explain":"réduire 是减少；produire 是生产；recycler 是回收。","source":"词汇 · 环境"},{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"listen","title":"听音辨词：环境与生态","body":"打开 对话页的 d27 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"réduire\">réduire</span>（减少）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d27","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Grâce au recyclage, nous réduisons les déchets.\">Grâce au recyclage, nous réduisons les déchets.</span>（多亏回收，我们减少了垃圾。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：环境与生态 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"l'environnement\">l'environnement</span> <span class=\"fr\" data-fr=\"le recyclage\">le recyclage</span> <span class=\"fr\" data-fr=\"un déchet\">un déchet</span> <span class=\"fr\" data-fr=\"le climat\">le climat</span> <span class=\"fr\" data-fr=\"l'énergie\">l'énergie</span> <span class=\"fr\" data-fr=\"réduire\">réduire</span>。说不出来的词立刻回到 vocab.html#t20 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t20","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:环境与生态"}]}]},{"day":2,"theme":"语法 · 原因连接词","type":"grammar","steps":[{"type":"grammar","title":"语法点：原因连接词","body":"【原因连接词】表达原因可用 parce que、car、comme、puisque、grâce à、à cause de；表达目的时，同主语用 pour 加不定式，不同主语用 pour que 或 afin que 加虚拟式。注意 grâce à 表正面原因，à cause de 表负面原因，两者不能混用。 例句：<span class=\"fr\" data-fr=\"Grâce au recyclage, nous réduisons les déchets.\">Grâce au recyclage, nous réduisons les déchets.</span>（多亏回收，我们减少了垃圾。）；<span class=\"fr\" data-fr=\"Je trie mes déchets pour que la planète aille mieux.\">Je trie mes déchets pour que la planète aille mieux.</span>（我分类垃圾，为的是让地球变得更好。）。对照 grammar-b1b2.html#conn-cause 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#conn-cause","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5013","level":"B1","skill":"grammar","prompt":"表达正面原因（多亏）应用？","options":["grâce à","à cause de","malgré"],"answer":"grâce à","explain":"grâce à 表正面原因；à cause de 表负面原因；malgré 表让步。","source":"语法 · 原因连接词"},{"ref":"bank:grammar:B1:连接词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#conn-cause 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Grâce au recyclage, nous réduisons les déchets.\">Grâce au recyclage, nous réduisons les déchets.</span>（多亏回收，我们减少了垃圾。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#conn-cause","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5014","level":"B1","skill":"grammar","prompt":"主从句主语不同时表达目的应用？","options":["pour que 加虚拟式","pour 加不定式","parce que"],"answer":"pour que 加虚拟式","explain":"同主语用 pour 加不定式，不同主语用 pour que 或 afin que 加虚拟式。","source":"语法 · 目的连接词"},{"ref":"bank:grammar:B1:连接词"}]},{"type":"read","title":"在短文里找原因连接词","body":"在 grammar-b1b2.html#conn-cause 的例句和章末小测里挑 5 句，圈出所有属于「原因连接词」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#conn-cause","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Grâce au recyclage, nous réduisons les déchets.\">Grâce au recyclage, nous réduisons les déchets.</span>（多亏回收，我们减少了垃圾。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，原因连接词 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：目的连接词","body":"今天再回 grammar-b1b2.html#conn-but 看一遍 目的连接词，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#conn-but","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:连接词"}]}]},{"day":3,"theme":"精听 · 对话页的 d27 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d27 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d27","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5007","level":"B1","skill":"listening","prompt":"听到 /a koz də la plyi/ 时表示？","options":["因为下雨（负面原因）","多亏下雨","尽管下雨"],"answer":"因为下雨（负面原因）","explain":"à cause de 引出负面原因。","source":"语法 · 原因连接词"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段环保政策讨论，记录正反双方各 3 个理由。","src":"dialogue.html#d27","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"l'environnement\">l'environnement</span>（环境）、<span class=\"fr\" data-fr=\"le recyclage\">le recyclage</span>（回收）、<span class=\"fr\" data-fr=\"un déchet\">un déchet</span>（垃圾）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t20","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「原因连接词 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d27","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 观点陈述与论述段写作","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：就「个人能否影响气候变化」陈述 3 分钟（观点、2 个理由、1 个例子）。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5004","level":"B1","skill":"speaking","prompt":"陈述环保观点时，最有力的结构是？","options":["观点加 2 个理由加 1 个例子","只喊口号","只讲个人经历"],"answer":"观点加 2 个理由加 1 个例子","explain":"论述要有观点、理由与例证三层，才有说服力。","source":"口语 · 论述结构"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d27 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、原因连接词 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d27","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"le climat\">le climat</span>（气候）、<span class=\"fr\" data-fr=\"l'énergie\">l'énergie</span>（能源）、<span class=\"fr\" data-fr=\"réduire\">réduire</span>（减少）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t20 再看一遍例句。","src":"vocab.html#t20","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 观点陈述与论述段写作","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读 2 篇 600 词对立观点的环保文章。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5007","level":"B1","skill":"reading","prompt":"读两篇对立观点文章时，最有用的做法是？","options":["做正反理由对照表","只读支持自己观点的一篇","背下所有生词"],"answer":"做正反理由对照表","explain":"对照表能快速看出双方论据与分歧点，为写作积累素材。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"l'environnement\">l'environnement</span>（环境）、<span class=\"fr\" data-fr=\"le recyclage\">le recyclage</span>（回收）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t20","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#conn-cause，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#conn-cause","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:连接词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「原因连接词」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 观点陈述与论述段写作","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 200 词论述段（引言 1 句、论点 2 段、结论 1 句）。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5004","level":"B1","skill":"writing","prompt":"论述段结论句的常见开头是？","options":["En conclusion,","Premièrement,","Par exemple,"],"answer":"En conclusion,","explain":"结论段用 En conclusion 或 Pour conclure；Premièrement 用于展开，Par exemple 用于举例。","source":"写作 · 论述段"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#conn-cause，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#conn-cause","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:连接词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「原因连接词」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"l'environnement\">l'environnement</span>（环境）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 观点陈述与论述段写作","type":"review","steps":[{"type":"review","title":"本周回顾：环境与生态：观点陈述与论述段写作","body":"这一周围绕「环境与生态：观点陈述与论述段写作」展开：语法主线是 原因连接词，词汇主线是 环境与生态。先用 3 句话口头复述本周学了什么，再打开日历页第 30 周清单逐条核对里程碑。","src":"calendar.html#wk-30","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"review","title":"语法复盘：原因连接词","body":"从 grammar-b1b2.html#conn-cause 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#conn-cause","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:连接词"}]},{"type":"review","title":"词汇自测：环境与生态","body":"遮住中文看 vocab.html#t20 的 6 个核心词：<span class=\"fr\" data-fr=\"l'environnement\">l'environnement</span> <span class=\"fr\" data-fr=\"le recyclage\">le recyclage</span> <span class=\"fr\" data-fr=\"un déchet\">un déchet</span> <span class=\"fr\" data-fr=\"le climat\">le climat</span> <span class=\"fr\" data-fr=\"l'énergie\">l'énergie</span> <span class=\"fr\" data-fr=\"réduire\">réduire</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t20","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5015","level":"B1","skill":"vocab","prompt":"« un déchet » 的意思是？","options":["垃圾","损失","回收站"],"answer":"垃圾","explain":"déchet 是垃圾、废弃物；dégât 是损失；déchetterie 是垃圾站。","source":"词汇 · 环境"},{"id":"q-vocab-b1-5016","level":"B1","skill":"vocab","prompt":"« l'énergie » 的意思是？","options":["能源","精力","引擎"],"answer":"能源","explain":"énergie 可指能源，也可指精力；moteur 是引擎。","source":"词汇 · 环境"},{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d27","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5008","level":"B1","skill":"listening","prompt":"讨论中 « d'un côté… de l'autre… » 的作用是？","options":["引出对立双方","表示因果","表示时间"],"answer":"引出对立双方","explain":"这个结构用于并列对立观点，是辩论材料里的高频框架。","source":"考试 · 听力策略"},{"id":"q-read-b1-5008","level":"B1","skill":"reading","prompt":"« puisque » 与 « parce que » 的差别是？","options":["puisque 引出已知原因","puisque 表示目的","两者完全相同"],"answer":"puisque 引出已知原因","explain":"puisque 引出的原因对话双方已知，带有「既然」的意味。","source":"语法 · 原因连接词"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 原因连接词 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#conn-cause 再核对一次。","src":"grammar-b1b2.html#conn-but","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5015","level":"B1","skill":"grammar","prompt":"« Je trie pour que la planète ___ mieux. »（aller）","options":["aille","va","ira"],"answer":"aille","explain":"pour que 后接虚拟式，aller 的虚拟式为 aille。","source":"语法 · 目的连接词"},{"id":"q-gram-b1-5016","level":"B1","skill":"grammar","prompt":"下列哪句目的表达有误？","options":["Je fais du vélo pour que réduire la pollution.","Je fais du vélo pour réduire la pollution.","Je fais du vélo afin de réduire la pollution."],"answer":"Je fais du vélo pour que réduire la pollution.","explain":"同主语时 pour 后直接接不定式，不能加 que；pour que 需要从句加虚拟式。","source":"语法 · 目的连接词"},{"ref":"bank:grammar:B1:连接词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":31,"level":"B1","theme":"被动语态与媒体信息处理","days":[{"day":1,"theme":"词汇 · 媒体与娱乐","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：媒体与娱乐","body":"本周词汇主战场是媒体与娱乐（Les médias et les loisirs）。先到 vocab.html#t16 把词表扫一遍，把 <span class=\"fr\" data-fr=\"un journal\">un journal</span>（报纸）、<span class=\"fr\" data-fr=\"une information\">une information</span>（信息；新闻）、<span class=\"fr\" data-fr=\"une source\">une source</span>（来源）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t16","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5017","level":"B1","skill":"vocab","prompt":"« une source » 的意思是？","options":["来源","出口","结局"],"answer":"来源","explain":"source 指信息来源，也可指泉源；sortie 是出口。","source":"词汇 · 媒体"},{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"vocab","title":"搭配与辨析：une rumeur / vérifier","body":"把 <span class=\"fr\" data-fr=\"une rumeur\">une rumeur</span>（传闻）和 <span class=\"fr\" data-fr=\"vérifier\">vérifier</span>（核实）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t16","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5018","level":"B1","skill":"vocab","prompt":"« vérifier » 的意思是？","options":["核实","发表","怀疑"],"answer":"核实","explain":"vérifier 是核实；publier 是发表；douter 是怀疑。","source":"词汇 · 媒体"},{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"listen","title":"听音辨词：媒体与娱乐","body":"打开 对话页的 d34 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un titre\">un titre</span>（标题）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d34","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"La loi a été adoptée par le Parlement.\">La loi a été adoptée par le Parlement.</span>（这项法律由议会通过。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：媒体与娱乐 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un journal\">un journal</span> <span class=\"fr\" data-fr=\"une information\">une information</span> <span class=\"fr\" data-fr=\"une source\">une source</span> <span class=\"fr\" data-fr=\"une rumeur\">une rumeur</span> <span class=\"fr\" data-fr=\"vérifier\">vérifier</span> <span class=\"fr\" data-fr=\"un titre\">un titre</span>。说不出来的词立刻回到 vocab.html#t16 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t16","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]}]},{"day":2,"theme":"语法 · 被动态构成","type":"grammar","steps":[{"type":"grammar","title":"语法点：被动态构成","body":"【被动态构成】被动语态由「être 加过去分词加 par 加施动者」构成，过去分词要与主语性数配合，时态由 être 体现。施动者是情感或状态的来源时用 de；日常法语更常用代动词被动（Ce vin se boit frais）或 on 来替代被动。 例句：<span class=\"fr\" data-fr=\"La loi a été adoptée par le Parlement.\">La loi a été adoptée par le Parlement.</span>（这项法律由议会通过。）；<span class=\"fr\" data-fr=\"Ce journal se vend partout en France.\">Ce journal se vend partout en France.</span>（这份报纸在法国各地都有卖。）。对照 grammar-b1b2.html#passif-formation 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#passif-formation","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5017","level":"B1","skill":"grammar","prompt":"« Le journal est lu par Marie. » 是被动语态吗？","options":["是，施动者由 par 引出","不是，是主动句","不是，是代动词"],"answer":"是，施动者由 par 引出","explain":"être 加过去分词加 par 加施动者构成被动语态。","source":"语法 · 被动语态"},{"ref":"bank:grammar:B1:被动"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 被动态构成 的规则和两个例句，再打开 grammar-b1b2.html#passif-formation 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#passif-formation","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5018","level":"B1","skill":"grammar","prompt":"下面哪个是更自然的被动替代形式？","options":["Ce livre se vend bien.","Ce livre est vendu bien par.","On se vend ce livre."],"answer":"Ce livre se vend bien.","explain":"代动词被动比 être 加过去分词更口语、更自然。","source":"语法 · 代动词被动"},{"ref":"bank:grammar:B1:被动"}]},{"type":"read","title":"在短文里找被动态构成","body":"在 grammar-b1b2.html#passif-formation 的例句和章末小测里挑 5 句，圈出所有属于「被动态构成」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#passif-formation","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"La loi a été adoptée par le Parlement.\">La loi a été adoptée par le Parlement.</span>（这项法律由议会通过。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，被动态构成 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：代动词被动与 on 替代","body":"今天再回 grammar-b1b2.html#passif-pronominal 看一遍 代动词被动与 on 替代，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#passif-pronominal","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:被动"}]}]},{"day":3,"theme":"精听 · 对话页的 d34 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d34 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d34","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5009","level":"B1","skill":"listening","prompt":"听到 /la lwa a ete adɔpte/ 时是什么结构？","options":["被动语态","代动词","虚拟式"],"answer":"被动语态","explain":"a été 加过去分词构成复合过去时的被动形式。","source":"语法 · 被动语态"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段新闻报道，把听到的被动句换成主动句。","src":"dialogue.html#d34","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un journal\">un journal</span>（报纸）、<span class=\"fr\" data-fr=\"une information\">une information</span>（信息；新闻）、<span class=\"fr\" data-fr=\"une source\">une source</span>（来源）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t16","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「被动态构成 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d34","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 被动语态与媒体信息处理","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：概括一条新闻并评价其信息来源是否可靠，共 3 分钟。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5005","level":"B1","skill":"speaking","prompt":"评价新闻来源可靠性时，应该问？","options":["信息来自谁、是否可核实","标题是否吸引人","文章有多长"],"answer":"信息来自谁、是否可核实","explain":"评估来源与可核实性是判断信息可靠性的核心。","source":"口语 · 媒体素养"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d34 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、被动态构成 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d34","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une rumeur\">une rumeur</span>（传闻）、<span class=\"fr\" data-fr=\"vérifier\">vérifier</span>（核实）、<span class=\"fr\" data-fr=\"un titre\">un titre</span>（标题）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t16 再看一遍例句。","src":"vocab.html#t16","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 被动语态与媒体信息处理","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读 3 篇不同立场的同一事件报道，做立场对比表。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5009","level":"B1","skill":"reading","prompt":"对比三家媒体的报道，主要看？","options":["用词与强调重点的差异","字数多少","排版风格"],"answer":"用词与强调重点的差异","explain":"同一事件的不同措辞体现立场差异，这是媒体分析的关键。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「被动态构成」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un journal\">un journal</span>（报纸）、<span class=\"fr\" data-fr=\"une information\">une information</span>（信息；新闻）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t16","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#passif-formation，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#passif-formation","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:被动"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「被动态构成」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 被动语态与媒体信息处理","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 200 词分析：同一事件三家媒体怎么描述。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5005","level":"B1","skill":"writing","prompt":"分析媒体时最合适的开头是？","options":["Le même événement est présenté de façon différente selon les journaux.","Tous les journaux mentent.","Je n'aime pas les journaux."],"answer":"Le même événement est présenté de façon différente selon les journaux.","explain":"书面分析要客观陈述现象再举证据，避免情绪化断言。","source":"写作 · 媒体分析"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#passif-formation，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#passif-formation","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:被动"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「被动态构成」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un journal\">un journal</span>（报纸）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 被动语态与媒体信息处理","type":"review","steps":[{"type":"review","title":"本周回顾：被动语态与媒体信息处理","body":"这一周围绕「被动语态与媒体信息处理」展开：语法主线是 被动态构成，词汇主线是 媒体与娱乐。先用 3 句话口头复述本周学了什么，再打开日历页第 31 周清单逐条核对里程碑。","src":"calendar.html#wk-31","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"review","title":"语法复盘：被动态构成","body":"从 grammar-b1b2.html#passif-formation 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#passif-formation","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:被动"}]},{"type":"review","title":"词汇自测：媒体与娱乐","body":"遮住中文看 vocab.html#t16 的 6 个核心词：<span class=\"fr\" data-fr=\"un journal\">un journal</span> <span class=\"fr\" data-fr=\"une information\">une information</span> <span class=\"fr\" data-fr=\"une source\">une source</span> <span class=\"fr\" data-fr=\"une rumeur\">une rumeur</span> <span class=\"fr\" data-fr=\"vérifier\">vérifier</span> <span class=\"fr\" data-fr=\"un titre\">un titre</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t16","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5019","level":"B1","skill":"vocab","prompt":"« une rumeur » 的意思是？","options":["传闻","新闻","广告"],"answer":"传闻","explain":"rumeur 是传闻、谣言；nouvelle 是新闻；publicité 是广告。","source":"词汇 · 媒体"},{"id":"q-vocab-b1-5020","level":"B1","skill":"vocab","prompt":"« un titre » 在媒体语境里指？","options":["标题","头衔","票据"],"answer":"标题","explain":"titre 在媒体里指标题，也可指头衔或票据。","source":"词汇 · 媒体"},{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d34","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5010","level":"B1","skill":"listening","prompt":"新闻里 « selon une source anonyme » 表示？","options":["据匿名来源","据官方数据","据记者的判断"],"answer":"据匿名来源","explain":"source anonyme 是匿名来源，可靠性需要打折。","source":"词汇 · 媒体"},{"id":"q-read-b1-5010","level":"B1","skill":"reading","prompt":"被动语态里过去分词要？","options":["与主语性数配合","保持不变","变成现在分词"],"answer":"与主语性数配合","explain":"être 作助动词时，过去分词必须与主语性数一致。","source":"语法 · 被动语态"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 被动态构成 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#passif-formation 再核对一次。","src":"grammar-b1b2.html#passif-pronominal","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5019","level":"B1","skill":"grammar","prompt":"« Les billets ___ vendus en ligne. »","options":["sont","est","a"],"answer":"sont","explain":"主语是复数，être 用 sont，分词配合成 vendus。","source":"语法 · 被动语态"},{"id":"q-gram-b1-5020","level":"B1","skill":"grammar","prompt":"情感类施动者一般用哪个介词？","options":["de","par","à"],"answer":"de","explain":"表示情感或状态来源的施动者用 de，如 aimé de tous；具体动作的施动者用 par。","source":"语法 · 被动语态"},{"ref":"bank:grammar:B1:被动"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":32,"level":"B1","theme":"分词式与科技话题","days":[{"day":1,"theme":"词汇 · 科技与互联网","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：科技与互联网","body":"科技与互联网（La technologie et Internet）是这一周要反复见面的主题域。打开 vocab.html#t15，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"une application\">une application</span>（应用）、<span class=\"fr\" data-fr=\"un réseau\">un réseau</span>（网络）、<span class=\"fr\" data-fr=\"les données\">les données</span>（数据）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t15","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5021","level":"B1","skill":"vocab","prompt":"« les données » 的意思是？","options":["数据","日期","礼物"],"answer":"数据","explain":"données 是数据；dates 是日期；dons 是礼物。","source":"词汇 · 科技"},{"ref":"bank:vocab:A2:科技与互联网"}]},{"type":"vocab","title":"搭配与辨析：la vie privée / un algorithme","body":"<span class=\"fr\" data-fr=\"la vie privée\">la vie privée</span>（隐私）与 <span class=\"fr\" data-fr=\"un algorithme\">un algorithme</span>（算法）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t15","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5022","level":"B1","skill":"vocab","prompt":"« la vie privée » 的意思是？","options":["隐私","私人场地","私人财产"],"answer":"隐私","explain":"vie privée 指隐私，也指私生活。","source":"词汇 · 科技"},{"ref":"bank:vocab:A2:科技与互联网"}]},{"type":"listen","title":"听音辨词：科技与互联网","body":"打开 对话页的 d40 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"connecté\">connecté</span>（联网的）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d40","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"C'est une application permettant de gérer son budget.\">C'est une application permettant de gérer son budget.</span>（这是一个能管理预算的应用。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：科技与互联网 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une application\">une application</span> <span class=\"fr\" data-fr=\"un réseau\">un réseau</span> <span class=\"fr\" data-fr=\"les données\">les données</span> <span class=\"fr\" data-fr=\"la vie privée\">la vie privée</span> <span class=\"fr\" data-fr=\"un algorithme\">un algorithme</span> <span class=\"fr\" data-fr=\"connecté\">connecté</span>。说不出来的词立刻回到 vocab.html#t15 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t15","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:科技与互联网"}]}]},{"day":2,"theme":"语法 · 现在分词","type":"grammar","steps":[{"type":"grammar","title":"语法点：现在分词","body":"【现在分词】现在分词以 -ant 结尾，用作动词时不变形，可以代替 qui 从句或原因从句；副动词是 en 加现在分词，表示同时、方式或条件，主语必须与主句一致。复合过去分词 ayant / étant 加过去分词表示先发生的动作。 例句：<span class=\"fr\" data-fr=\"C'est une application permettant de gérer son budget.\">C'est une application permettant de gérer son budget.</span>（这是一个能管理预算的应用。）；<span class=\"fr\" data-fr=\"Il répond aux messages en écoutant de la musique.\">Il répond aux messages en écoutant de la musique.</span>（他一边听音乐一边回消息。）。对照 grammar-b1b2.html#participe-present 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#participe-present","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5021","level":"B1","skill":"grammar","prompt":"现在分词 « parlant » 的词尾是？","options":["-ant","-ent","-é"],"answer":"-ant","explain":"现在分词的构成是：nous 现在时去掉 -ons 再加 -ant。","source":"语法 · 现在分词"},{"ref":"bank:grammar:B1:分词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#participe-present 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"C'est une application permettant de gérer son budget.\">C'est une application permettant de gérer son budget.</span>（这是一个能管理预算的应用。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#participe-present","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5022","level":"B1","skill":"grammar","prompt":"副动词的构成是？","options":["en 加现在分词","en 加过去分词","à 加不定式"],"answer":"en 加现在分词","explain":"副动词是 en 加现在分词，表示同时、方式或条件。","source":"语法 · 副动词"},{"ref":"bank:grammar:B1:分词"}]},{"type":"read","title":"在短文里找现在分词","body":"在 grammar-b1b2.html#participe-present 的例句和章末小测里挑 5 句，圈出所有属于「现在分词」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#participe-present","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"C'est une application permettant de gérer son budget.\">C'est une application permettant de gérer son budget.</span>（这是一个能管理预算的应用。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，现在分词 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：副动词","body":"今天再回 grammar-b1b2.html#gerondif 看一遍 副动词，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#gerondif","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:分词"}]}]},{"day":3,"theme":"精听 · 对话页的 d40 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d40 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d40","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5011","level":"B1","skill":"listening","prompt":"听到 /ɑ̃ ekutɑ̃/ 时应识别为？","options":["副动词","现在分词","过去分词"],"answer":"副动词","explain":"en 加现在分词构成副动词，/ɑ̃/ 是 en 的读音。","source":"语法 · 副动词"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段科技播客，用分词式改写其中 8 句。","src":"dialogue.html#d40","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une application\">une application</span>（应用）、<span class=\"fr\" data-fr=\"un réseau\">un réseau</span>（网络）、<span class=\"fr\" data-fr=\"les données\">les données</span>（数据）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t15","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:科技与互联网"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「现在分词 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d40","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 分词式与科技话题","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：讲「我最常用的三个 App 及原因」3 分钟。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5006","level":"B1","skill":"speaking","prompt":"介绍常用 App 时，最高效的结构是？","options":["先说用途再用分词补充功能","只念应用名称","只讲缺点"],"answer":"先说用途再用分词补充功能","explain":"用现在分词补充应用的功能，句子更紧凑。","source":"口语 · 结构"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d40 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、现在分词 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d40","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"la vie privée\">la vie privée</span>（隐私）、<span class=\"fr\" data-fr=\"un algorithme\">un algorithme</span>（算法）、<span class=\"fr\" data-fr=\"connecté\">connecté</span>（联网的）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t15 再看一遍例句。","src":"vocab.html#t15","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:科技与互联网"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 分词式与科技话题","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读一篇 700 词科技评论，标出分词结构。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5011","level":"B1","skill":"reading","prompt":"« une application permettant… » 中 permettant 相当于？","options":["qui permet","que permet","dont permet"],"answer":"qui permet","explain":"现在分词作动词时可以代替 qui 引导的关系从句。","source":"语法 · 现在分词"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une application\">une application</span>（应用）、<span class=\"fr\" data-fr=\"un réseau\">un réseau</span>（网络）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t15","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:科技与互联网"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#participe-present，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#participe-present","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:分词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「现在分词」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 分词式与科技话题","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 200 词短文：技术让生活更好还是更焦虑（用 4 个分词结构）。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5006","level":"B1","skill":"writing","prompt":"「我一边工作一边听音乐」应说？","options":["Je travaille en écoutant de la musique.","Je travaille en écouter de la musique.","Je travaille écoutant de la musique."],"answer":"Je travaille en écoutant de la musique.","explain":"副动词是 en 加现在分词，en 不能省，分词也不能换成不定式。","source":"语法 · 副动词"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#participe-present，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#participe-present","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:分词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「现在分词」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une application\">une application</span>（应用）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 分词式与科技话题","type":"review","steps":[{"type":"review","title":"本周回顾：分词式与科技话题","body":"这一周围绕「分词式与科技话题」展开：语法主线是 现在分词，词汇主线是 科技与互联网。先用 3 句话口头复述本周学了什么，再打开日历页第 32 周清单逐条核对里程碑。","src":"calendar.html#wk-32","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:科技与互联网"}]},{"type":"review","title":"语法复盘：现在分词","body":"从 grammar-b1b2.html#participe-present 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#participe-present","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:分词"}]},{"type":"review","title":"词汇自测：科技与互联网","body":"遮住中文看 vocab.html#t15 的 6 个核心词：<span class=\"fr\" data-fr=\"une application\">une application</span> <span class=\"fr\" data-fr=\"un réseau\">un réseau</span> <span class=\"fr\" data-fr=\"les données\">les données</span> <span class=\"fr\" data-fr=\"la vie privée\">la vie privée</span> <span class=\"fr\" data-fr=\"un algorithme\">un algorithme</span> <span class=\"fr\" data-fr=\"connecté\">connecté</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t15","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5023","level":"B1","skill":"vocab","prompt":"« un algorithme » 的意思是？","options":["算法","电路","账户"],"answer":"算法","explain":"algorithme 是算法；circuit 是电路；compte 是账户。","source":"词汇 · 科技"},{"id":"q-vocab-b1-5024","level":"B1","skill":"vocab","prompt":"« connecté » 的意思是？","options":["联网的","被保护的","被删除的"],"answer":"联网的","explain":"connecté 表示已联网、已连接。","source":"词汇 · 科技"},{"ref":"bank:vocab:A2:科技与互联网"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d40","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5012","level":"B1","skill":"listening","prompt":"播客里 « en utilisant » 表示？","options":["通过使用（方式）","在使用之后","如果不使用"],"answer":"通过使用（方式）","explain":"副动词可表示方式，en utilisant 相当于「通过使用」。","source":"语法 · 副动词"},{"id":"q-read-b1-5012","level":"B1","skill":"reading","prompt":"« Ayant fini son rapport, il est parti. » 中 ayant fini 表示？","options":["先发生的动作","同时发生","后发生的动作"],"answer":"先发生的动作","explain":"复合过去分词由 ayant / étant 加过去分词构成，表示先时性。","source":"语法 · 复合过去分词"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 现在分词 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#participe-present 再核对一次。","src":"grammar-b1b2.html#gerondif","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5023","level":"B1","skill":"grammar","prompt":"« ___ ses données, il a protégé sa vie privée. »（sauvegarder，先发生）","options":["Ayant sauvegardé","Sauvegardant","Sauvegardé"],"answer":"Ayant sauvegardé","explain":"表示先发生的动作时用复合过去分词 ayant 加过去分词。","source":"语法 · 复合过去分词"},{"id":"q-gram-b1-5024","level":"B1","skill":"grammar","prompt":"使用副动词最重要的限制是？","options":["副动词与主句的主语必须一致","不能带宾语","只能放在句首"],"answer":"副动词与主句的主语必须一致","explain":"副动词的主语必须与主句一致，否则句子会含糊。","source":"语法 · 副动词"},{"ref":"bank:grammar:B1:分词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":33,"level":"B1","theme":"阶段测：DELF B1 模拟（词汇 2000）","days":[{"day":1,"theme":"词汇 · 社会与议题","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：社会与议题","body":"本周词汇主战场是社会与议题（La société et les débats）。先到 vocab.html#t19 把词表扫一遍，把 <span class=\"fr\" data-fr=\"une épreuve\">une épreuve</span>（考试科目）、<span class=\"fr\" data-fr=\"un critère\">un critère</span>（标准）、<span class=\"fr\" data-fr=\"une argumentation\">une argumentation</span>（论证）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t19","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5025","level":"B1","skill":"vocab","prompt":"« une épreuve » 的意思是？","options":["考试科目","证据","尝试"],"answer":"考试科目","explain":"épreuve 指考试项目或考验；preuve 是证据；essai 是尝试。","source":"词汇 · 考试"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"vocab","title":"搭配与辨析：un point faible / un objectif","body":"把 <span class=\"fr\" data-fr=\"un point faible\">un point faible</span>（弱项）和 <span class=\"fr\" data-fr=\"un objectif\">un objectif</span>（目标）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t19","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5026","level":"B1","skill":"vocab","prompt":"« s'entraîner » 的意思是？","options":["训练","拖拽","进入"],"answer":"训练","explain":"s'entraîner 是训练、练习；entraîner 还有「导致」的意思。","source":"词汇 · 学习"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"listen","title":"听音辨词：社会与议题","body":"打开 对话页的 d30 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"s'entraîner\">s'entraîner</span>（训练）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d30","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Il est essentiel que chacun puisse participer.\">Il est essentiel que chacun puisse participer.</span>（每个人都能够参与是至关重要的。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：社会与议题 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une épreuve\">une épreuve</span> <span class=\"fr\" data-fr=\"un critère\">un critère</span> <span class=\"fr\" data-fr=\"une argumentation\">une argumentation</span> <span class=\"fr\" data-fr=\"un point faible\">un point faible</span> <span class=\"fr\" data-fr=\"un objectif\">un objectif</span> <span class=\"fr\" data-fr=\"s'entraîner\">s'entraîner</span>。说不出来的词立刻回到 vocab.html#t19 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t19","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]}]},{"day":2,"theme":"语法 · 虚拟式触发词分类","type":"grammar","steps":[{"type":"grammar","title":"语法点：虚拟式触发词分类","body":"【虚拟式触发词分类】这一周按考试结构限时做一套 B1 模拟：听力 25 分钟、阅读 45 分钟、写作 45 分钟、口语 15 分钟。语法专项集中检查虚拟式、被动、关系代词与时态配合，正确率目标不低于 80%；词汇自测目标 2000 词，认词率不低于 85%。 例句：<span class=\"fr\" data-fr=\"Il est essentiel que chacun puisse participer.\">Il est essentiel que chacun puisse participer.</span>（每个人都能够参与是至关重要的。）；<span class=\"fr\" data-fr=\"La décision a été prise après un long débat.\">La décision a été prise après un long débat.</span>（这个决定经过长时间辩论才作出。）。对照 grammar-b1b2.html#subj-declencheurs 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#subj-declencheurs","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5025","level":"B1","skill":"grammar","prompt":"« Il est essentiel que chacun ___ participer. »（pouvoir）","options":["puisse","peut","pourra"],"answer":"puisse","explain":"无人称判断结构后接虚拟式，pouvoir 的虚拟式为 puisse。","source":"语法 · 虚拟式"},{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 虚拟式触发词分类 的规则和两个例句，再打开 grammar-b1b2.html#subj-declencheurs 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#subj-declencheurs","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5026","level":"B1","skill":"grammar","prompt":"« La décision a été ___ après un débat. »（prendre）","options":["prise","pris","prendre"],"answer":"prise","explain":"被动语态里过去分词要与阴性主语 décision 配合。","source":"语法 · 被动语态"},{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"read","title":"在短文里找虚拟式触发词分类","body":"在 grammar-b1b2.html#subj-declencheurs 的例句和章末小测里挑 5 句，圈出所有属于「虚拟式触发词分类」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#subj-declencheurs","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Il est essentiel que chacun puisse participer.\">Il est essentiel que chacun puisse participer.</span>（每个人都能够参与是至关重要的。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，虚拟式触发词分类 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：被动态构成","body":"今天再回 grammar-b1b2.html#passif-formation 看一遍 被动态构成，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#passif-formation","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]}]},{"day":3,"theme":"精听 · 对话页的 d30 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d30 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d30","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5013","level":"B1","skill":"listening","prompt":"B1 听力中「同义替换」难点指？","options":["原文与题干表达不同但意思相同","语速太快","词汇太难"],"answer":"原文与题干表达不同但意思相同","explain":"听力题常把原文表达换成题干说法，需要识别等价关系。","source":"考试 · 听力策略"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：限时做 B1 听力（25 分钟），做完对答案并归类错因。","src":"dialogue.html#d30","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une épreuve\">une épreuve</span>（考试科目）、<span class=\"fr\" data-fr=\"un critère\">un critère</span>（标准）、<span class=\"fr\" data-fr=\"une argumentation\">une argumentation</span>（论证）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t19","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「虚拟式触发词分类 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d30","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · DELF B1 模拟（词汇 2000）","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：录 5 分钟陈述加自问自答式辩论。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5007","level":"B1","skill":"speaking","prompt":"B1 口语辩论的常见框架是？","options":["陈述观点、举例、回应反驳","只念提纲","只讲故事"],"answer":"陈述观点、举例、回应反驳","explain":"辩论要有观点、例证与对反驳的回应三部分。","source":"口语 · 辩论"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d30 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、虚拟式触发词分类 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d30","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un point faible\">un point faible</span>（弱项）、<span class=\"fr\" data-fr=\"un objectif\">un objectif</span>（目标）、<span class=\"fr\" data-fr=\"s'entraîner\">s'entraîner</span>（训练）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t19 再看一遍例句。","src":"vocab.html#t19","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · DELF B1 模拟（词汇 2000）","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：限时做 B1 阅读（45 分钟），统计同义替换类错题。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5013","level":"B1","skill":"reading","prompt":"B1 阅读 45 分钟内应该先做？","options":["快速浏览文章结构与题干","逐词精读","先写摘要"],"answer":"快速浏览文章结构与题干","explain":"先建立整体结构与题干要求，再定位细节，时间利用率最高。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「虚拟式触发词分类」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une épreuve\">une épreuve</span>（考试科目）、<span class=\"fr\" data-fr=\"un critère\">un critère</span>（标准）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t19","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#subj-declencheurs，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#subj-declencheurs","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「虚拟式触发词分类」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · DELF B1 模拟（词汇 2000）","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 200 词论说文，按「任务完成度、连贯、词汇、语法、拼写」五项打分。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5007","level":"B1","skill":"writing","prompt":"B1 论说文评分项里的「连贯」指？","options":["段落与连接词组织合理","字数达标","没有拼写错误"],"answer":"段落与连接词组织合理","explain":"连贯性检查逻辑连接与段落组织，与词汇、语法分项评分。","source":"写作 · 评分标准"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#subj-declencheurs，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#subj-declencheurs","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「虚拟式触发词分类」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une épreuve\">une épreuve</span>（考试科目）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · DELF B1 模拟（词汇 2000）","type":"review","steps":[{"type":"review","title":"本周回顾：阶段测：DELF B1 模拟（词汇 2000）","body":"这一周围绕「阶段测：DELF B1 模拟（词汇 2000）」展开：语法主线是 虚拟式触发词分类，词汇主线是 社会与议题。先用 3 句话口头复述本周学了什么，再打开日历页第 33 周清单逐条核对里程碑。","src":"calendar.html#wk-33","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"语法复盘：虚拟式触发词分类","body":"从 grammar-b1b2.html#subj-declencheurs 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#subj-declencheurs","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"review","title":"词汇自测：社会与议题","body":"遮住中文看 vocab.html#t19 的 6 个核心词：<span class=\"fr\" data-fr=\"une épreuve\">une épreuve</span> <span class=\"fr\" data-fr=\"un critère\">un critère</span> <span class=\"fr\" data-fr=\"une argumentation\">une argumentation</span> <span class=\"fr\" data-fr=\"un point faible\">un point faible</span> <span class=\"fr\" data-fr=\"un objectif\">un objectif</span> <span class=\"fr\" data-fr=\"s'entraîner\">s'entraîner</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t19","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5027","level":"B1","skill":"vocab","prompt":"« un critère » 的意思是？","options":["标准","批评","危机"],"answer":"标准","explain":"critère 是标准、准则；critique 是批评；crise 是危机。","source":"词汇 · 论述"},{"id":"q-vocab-b1-5028","level":"B1","skill":"vocab","prompt":"« une argumentation » 的意思是？","options":["论证","争吵","争论者"],"answer":"论证","explain":"argumentation 是论证、说理；dispute 是争吵。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d30","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5014","level":"B1","skill":"listening","prompt":"B1 听力错因里，「语速」问题的对策是？","options":["反复听快速语料并做笔记","只读原文","跳过生词"],"answer":"反复听快速语料并做笔记","explain":"语速问题需要靠大量真实语料输入与记笔记训练解决。","source":"考试 · 听力策略"},{"id":"q-read-b1-5014","level":"B1","skill":"reading","prompt":"关系代词 qui 与 que 的分工是？","options":["qui 作主语、que 作直接宾语","qui 作宾语、que 作主语","两者可互换"],"answer":"qui 作主语、que 作直接宾语","explain":"判断标准是先行词在从句里充当什么成分。","source":"语法 · 关系代词"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 虚拟式触发词分类 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#subj-declencheurs 再核对一次。","src":"grammar-b1b2.html#passif-formation","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5027","level":"B1","skill":"grammar","prompt":"下列哪个结构接虚拟式？","options":["il est normal que","je pense que","parce que"],"answer":"il est normal que","explain":"判断与评价类无人称结构后接虚拟式；je pense que 后接直陈式。","source":"语法 · 虚拟式触发词"},{"id":"q-gram-b1-5028","level":"B1","skill":"grammar","prompt":"「这本书被很多人读过」应说？","options":["Ce livre a été lu par beaucoup de gens.","Ce livre est lu beaucoup de gens.","Ce livre a lu par beaucoup de gens."],"answer":"Ce livre a été lu par beaucoup de gens.","explain":"被动语态的复合过去时是 a été 加过去分词，施动者由 par 引出。","source":"语法 · 被动语态"},{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":34,"level":"B1","theme":"逻辑连接词体系（原因/结果/对立/让步）","days":[{"day":1,"theme":"词汇 · 抽象概念与逻辑","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：抽象概念与逻辑","body":"抽象概念与逻辑（Les notions abstraites et la logique）是这一周要反复见面的主题域。打开 vocab.html#t24，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"pourtant\">pourtant</span>（然而）、<span class=\"fr\" data-fr=\"par conséquent\">par conséquent</span>（因此）、<span class=\"fr\" data-fr=\"malgré\">malgré</span>（尽管）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t24","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5029","level":"B1","skill":"vocab","prompt":"« pourtant » 的意思是？","options":["然而","因此","此外"],"answer":"然而","explain":"pourtant 表转折；par conséquent 表结果；de plus 表递进。","source":"词汇 · 逻辑连接"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"vocab","title":"搭配与辨析：certes / un argument","body":"<span class=\"fr\" data-fr=\"certes\">certes</span>（诚然）与 <span class=\"fr\" data-fr=\"un argument\">un argument</span>（论据）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t24","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5030","level":"B1","skill":"vocab","prompt":"« malgré » 后面接什么？","options":["名词","虚拟式从句","不定式"],"answer":"名词","explain":"malgré 是介词，后接名词；bien que 后接虚拟式从句。","source":"词汇 · 逻辑连接"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"listen","title":"听音辨词：抽象概念与逻辑","body":"打开 对话页的 d30 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"une conclusion\">une conclusion</span>（结论）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d30","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Il pleuvait, c'est pourquoi nous sommes restés.\">Il pleuvait, c'est pourquoi nous sommes restés.</span>（当时在下雨，所以我们留下了。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：抽象概念与逻辑 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"pourtant\">pourtant</span> <span class=\"fr\" data-fr=\"par conséquent\">par conséquent</span> <span class=\"fr\" data-fr=\"malgré\">malgré</span> <span class=\"fr\" data-fr=\"certes\">certes</span> <span class=\"fr\" data-fr=\"un argument\">un argument</span> <span class=\"fr\" data-fr=\"une conclusion\">une conclusion</span>。说不出来的词立刻回到 vocab.html#t24 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t24","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]}]},{"day":2,"theme":"语法 · 逻辑连接词大表","type":"grammar","steps":[{"type":"grammar","title":"语法点：逻辑连接词大表","body":"【逻辑连接词大表】结果连接用 donc、c'est pourquoi、par conséquent；转折用 cependant、pourtant、en revanche；让步用 bien que 加虚拟式、malgré 加名词，以及 certes… mais… 这一先承认后反驳的结构。把这些连接词用对，论证就不再是一条线到底。 例句：<span class=\"fr\" data-fr=\"Il pleuvait, c'est pourquoi nous sommes restés.\">Il pleuvait, c'est pourquoi nous sommes restés.</span>（当时在下雨，所以我们留下了。）；<span class=\"fr\" data-fr=\"Certes, ce projet coûte cher, mais il est nécessaire.\">Certes, ce projet coûte cher, mais il est nécessaire.</span>（这个项目确实贵，但很有必要。）。对照 grammar-b1b2.html#connecteurs 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#connecteurs","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5029","level":"B1","skill":"grammar","prompt":"« ___ il fasse froid, nous sortons. »","options":["Bien qu'","Malgré","Même si"],"answer":"Bien qu'","explain":"bien que 后接虚拟式从句；malgré 后接名词；même si 后接直陈式。","source":"语法 · 让步连接"},{"ref":"bank:grammar:B1:连接词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#connecteurs 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Il pleuvait, c'est pourquoi nous sommes restés.\">Il pleuvait, c'est pourquoi nous sommes restés.</span>（当时在下雨，所以我们留下了。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#connecteurs","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5030","level":"B1","skill":"grammar","prompt":"表达「因此」的连接词是？","options":["par conséquent","en revanche","pourtant"],"answer":"par conséquent","explain":"par conséquent 表结果；en revanche 与 pourtant 表转折。","source":"语法 · 结果连接词"},{"ref":"bank:grammar:B1:连接词"}]},{"type":"read","title":"在短文里找逻辑连接词大表","body":"在 grammar-b1b2.html#connecteurs 的例句和章末小测里挑 5 句，圈出所有属于「逻辑连接词大表」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#connecteurs","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Il pleuvait, c'est pourquoi nous sommes restés.\">Il pleuvait, c'est pourquoi nous sommes restés.</span>（当时在下雨，所以我们留下了。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，逻辑连接词大表 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：让步 concession","body":"今天再回 grammar-b1b2.html#conn-concession 看一遍 让步 concession，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#conn-concession","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:连接词"}]}]},{"day":3,"theme":"精听 · 对话页的 d30 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d30 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d30","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5015","level":"B1","skill":"listening","prompt":"辩论中 « certes… mais… » 的作用是？","options":["先承认再反驳","补充例子","总结观点"],"answer":"先承认再反驳","explain":"这个结构先让步承认对方的部分道理，再提出自己的反驳。","source":"语法 · 让步表达"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听辩论片段，标记每个连接词与其逻辑作用。","src":"dialogue.html#d30","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"pourtant\">pourtant</span>（然而）、<span class=\"fr\" data-fr=\"par conséquent\">par conséquent</span>（因此）、<span class=\"fr\" data-fr=\"malgré\">malgré</span>（尽管）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t24","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「逻辑连接词大表 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d30","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 逻辑连接词体系（原因/结果/对立/让步）","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：用 certes… mais… 结构就任一话题说 3 轮让步与反驳。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5008","level":"B1","skill":"speaking","prompt":"做让步与反驳时，最自然的顺序是？","options":["先承认对方一点，再给出反证","直接否定对方","只重复自己的观点"],"answer":"先承认对方一点，再给出反证","explain":"让步加反驳能让论证显得从容而有说服力。","source":"口语 · 辩论"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d30 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、逻辑连接词大表 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d30","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"certes\">certes</span>（诚然）、<span class=\"fr\" data-fr=\"un argument\">un argument</span>（论据）、<span class=\"fr\" data-fr=\"une conclusion\">une conclusion</span>（结论）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t24 再看一遍例句。","src":"vocab.html#t24","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 逻辑连接词体系（原因/结果/对立/让步）","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读一篇 800 词社论，画出论证结构图（论点、论据、让步、结论）。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5015","level":"B1","skill":"reading","prompt":"画论证结构图时，「让步」通常出现在？","options":["反方观点段与反驳段之间","文章开头","结论之后"],"answer":"反方观点段与反驳段之间","explain":"让步段承接反方观点，随后被反驳，位置在结论之前。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"pourtant\">pourtant</span>（然而）、<span class=\"fr\" data-fr=\"par conséquent\">par conséquent</span>（因此）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t24","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#connecteurs，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#connecteurs","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:连接词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「逻辑连接词大表」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 逻辑连接词体系（原因/结果/对立/让步）","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 200 词带让步段的论述，必须出现 pourtant、bien que、certes… mais。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5008","level":"B1","skill":"writing","prompt":"带让步段的论述里，「诚然」应说？","options":["Certes,","Donc,","Ensuite,"],"answer":"Certes,","explain":"Certes 引出让步；Donc 表结果；Ensuite 表时间顺序。","source":"写作 · 论述段"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#connecteurs，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#connecteurs","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:连接词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「逻辑连接词大表」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"pourtant\">pourtant</span>（然而）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 逻辑连接词体系（原因/结果/对立/让步）","type":"review","steps":[{"type":"review","title":"本周回顾：逻辑连接词体系（原因/结果/对立/让步）","body":"这一周围绕「逻辑连接词体系（原因/结果/对立/让步）」展开：语法主线是 逻辑连接词大表，词汇主线是 抽象概念与逻辑。先用 3 句话口头复述本周学了什么，再打开日历页第 34 周清单逐条核对里程碑。","src":"calendar.html#wk-34","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"review","title":"语法复盘：逻辑连接词大表","body":"从 grammar-b1b2.html#connecteurs 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#connecteurs","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:连接词"}]},{"type":"review","title":"词汇自测：抽象概念与逻辑","body":"遮住中文看 vocab.html#t24 的 6 个核心词：<span class=\"fr\" data-fr=\"pourtant\">pourtant</span> <span class=\"fr\" data-fr=\"par conséquent\">par conséquent</span> <span class=\"fr\" data-fr=\"malgré\">malgré</span> <span class=\"fr\" data-fr=\"certes\">certes</span> <span class=\"fr\" data-fr=\"un argument\">un argument</span> <span class=\"fr\" data-fr=\"une conclusion\">une conclusion</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t24","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5031","level":"B1","skill":"vocab","prompt":"« un argument » 的意思是？","options":["论据","争吵","争论者"],"answer":"论据","explain":"argument 是论据、理由；dispute 是争吵。","source":"词汇 · 论述"},{"id":"q-vocab-b1-5032","level":"B1","skill":"vocab","prompt":"« une conclusion » 的意思是？","options":["结论","引言","建议"],"answer":"结论","explain":"conclusion 是结论；introduction 是引言；conseil 是建议。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d30","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5016","level":"B1","skill":"listening","prompt":"听到 /ɑ̃ ʁəvɑ̃ʃ/ 时表示？","options":["相反地","因此","确实"],"answer":"相反地","explain":"en revanche 表示相反、另一方面，用于对比两个对立面。","source":"词汇 · 逻辑连接"},{"id":"q-read-b1-5016","level":"B1","skill":"reading","prompt":"« donc » 与 « pourtant » 的逻辑关系分别是？","options":["结果与转折","转折与结果","都是结果"],"answer":"结果与转折","explain":"donc 表结果，pourtant 表转折，两者方向相反。","source":"语法 · 逻辑连接词"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 逻辑连接词大表 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#connecteurs 再核对一次。","src":"grammar-b1b2.html#conn-concession","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5031","level":"B1","skill":"grammar","prompt":"« Il est intelligent, ___ il ne travaille pas. »（转折）","options":["pourtant","donc","parce que"],"answer":"pourtant","explain":"转折用 pourtant；donc 表结果，parce que 表原因。","source":"语法 · 逻辑连接词"},{"id":"q-gram-b1-5032","level":"B1","skill":"grammar","prompt":"« ___ son âge, il travaille vite. »","options":["Malgré","Bien que","Parce que"],"answer":"Malgré","explain":"malgré 后接名词短语 son âge；bien que 需要从句与虚拟式。","source":"语法 · 让步连接"},{"ref":"bank:grammar:B1:连接词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":35,"level":"B1","theme":"条件式与假设三型","days":[{"day":1,"theme":"词汇 · 社会与议题","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：社会与议题","body":"本周词汇主战场是社会与议题（La société et les débats）。先到 vocab.html#t19 把词表扫一遍，把 <span class=\"fr\" data-fr=\"une condition\">une condition</span>（条件）、<span class=\"fr\" data-fr=\"une hypothèse\">une hypothèse</span>（假设）、<span class=\"fr\" data-fr=\"un citoyen\">un citoyen</span>（公民）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t19","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5033","level":"B1","skill":"vocab","prompt":"« une hypothèse » 的意思是？","options":["假设","医院","节日"],"answer":"假设","explain":"hypothèse 是假设；hôpital 是医院；fête 是节日。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"vocab","title":"搭配与辨析：une politique / dépendre de","body":"把 <span class=\"fr\" data-fr=\"une politique\">une politique</span>（政策）和 <span class=\"fr\" data-fr=\"dépendre de\">dépendre de</span>（取决于）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t19","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5034","level":"B1","skill":"vocab","prompt":"« sinon » 的意思是？","options":["否则","既然","然而"],"answer":"否则","explain":"sinon 表示否则、要不然；puisque 是既然；pourtant 是然而。","source":"词汇 · 逻辑连接"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"listen","title":"听音辨词：社会与议题","body":"打开 对话页的 d30 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"sinon\">sinon</span>（否则）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d30","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Si tu viens, nous irons au cinéma.\">Si tu viens, nous irons au cinéma.</span>（如果你来，我们就去看电影。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：社会与议题 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une condition\">une condition</span> <span class=\"fr\" data-fr=\"une hypothèse\">une hypothèse</span> <span class=\"fr\" data-fr=\"un citoyen\">un citoyen</span> <span class=\"fr\" data-fr=\"une politique\">une politique</span> <span class=\"fr\" data-fr=\"dépendre de\">dépendre de</span> <span class=\"fr\" data-fr=\"sinon\">sinon</span>。说不出来的词立刻回到 vocab.html#t19 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t19","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]}]},{"day":2,"theme":"语法 · si 的三种假设句型","type":"grammar","steps":[{"type":"grammar","title":"语法点：si 的三种假设句型","body":"【si 的三种假设句型】si 的三种假设句型是：si 加现在时、主句用现在时或简单将来时（现实条件）；si 加未完成过去时、主句用条件式现在时（假设）；si 加愈过去时、主句用条件式过去时（反事实）。注意 si 引导的从句里永远不用将来时或条件式。 例句：<span class=\"fr\" data-fr=\"Si tu viens, nous irons au cinéma.\">Si tu viens, nous irons au cinéma.</span>（如果你来，我们就去看电影。）；<span class=\"fr\" data-fr=\"Si j'avais plus de temps, je voyagerais davantage.\">Si j'avais plus de temps, je voyagerais davantage.</span>（如果我有更多时间，我会多旅行。）。对照 grammar-b1b2.html#si-trois 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#si-trois","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5033","level":"B1","skill":"grammar","prompt":"« Si tu viens, nous ___ au cinéma. »","options":["irons","irions","étions allés"],"answer":"irons","explain":"现实条件用 si 加现在时，主句用简单将来时。","source":"语法 · 假设三型"},{"ref":"bank:grammar:B1:假设"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 si 的三种假设句型 的规则和两个例句，再打开 grammar-b1b2.html#si-trois 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#si-trois","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5034","level":"B1","skill":"grammar","prompt":"si 引导的从句里可以使用简单将来时吗？","options":["不可以","可以","只在正式语体里可以"],"answer":"不可以","explain":"si 引导的条件从句里不能用将来时或条件式，这是一条硬规则。","source":"语法 · 假设三型"},{"ref":"bank:grammar:B1:假设"}]},{"type":"read","title":"在短文里找si 的三种假设句型","body":"在 grammar-b1b2.html#si-trois 的例句和章末小测里挑 5 句，圈出所有属于「si 的三种假设句型」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#si-trois","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Si tu viens, nous irons au cinéma.\">Si tu viens, nous irons au cinéma.</span>（如果你来，我们就去看电影。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，si 的三种假设句型 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：条件式现在时：三大用法","body":"今天再回 grammar-b1b2.html#cond-usage 看一遍 条件式现在时：三大用法，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#cond-usage","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:假设"}]}]},{"day":3,"theme":"精听 · 对话页的 d30 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d30 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d30","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5017","level":"B1","skill":"listening","prompt":"听到 /si ʒavɛ ply də tɑ̃/ 对应哪一型假设？","options":["第二型（假设）","第一型（现实）","第三型（反事实）"],"answer":"第二型（假设）","explain":"si 加未完成过去时构成第二型假设。","source":"语法 · 假设三型"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听访谈中的假设句，判断属于哪一型。","src":"dialogue.html#d30","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une condition\">une condition</span>（条件）、<span class=\"fr\" data-fr=\"une hypothèse\">une hypothèse</span>（假设）、<span class=\"fr\" data-fr=\"un citoyen\">un citoyen</span>（公民）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t19","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「si 的三种假设句型 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d30","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 条件式与假设三型","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：就「如果我有一年空闲时间」做三种时态各 3 句的连锁表达。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5009","level":"B1","skill":"speaking","prompt":"「如果我有一年空闲时间」应说？","options":["Si j'avais un an de libre…","Si j'aurais un an de libre…","Si j'ai eu un an de libre…"],"answer":"Si j'avais un an de libre…","explain":"第二型假设里 si 从句用未完成过去时，只有主句才用条件式。","source":"语法 · 假设三型"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d30 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、si 的三种假设句型 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d30","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une politique\">une politique</span>（政策）、<span class=\"fr\" data-fr=\"dépendre de\">dépendre de</span>（取决于）、<span class=\"fr\" data-fr=\"sinon\">sinon</span>（否则）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t19 再看一遍例句。","src":"vocab.html#t19","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 条件式与假设三型","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页假设三型对比表与 si 的替代结构（au cas où、à condition que）。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5017","level":"B1","skill":"reading","prompt":"« au cas où » 后面接什么？","options":["条件式","现在时","简单将来时"],"answer":"条件式","explain":"au cas où 后接条件式，是 si 的替代结构之一。","source":"语法 · si 替代结构"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「si 的三种假设句型」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une condition\">une condition</span>（条件）、<span class=\"fr\" data-fr=\"une hypothèse\">une hypothèse</span>（假设）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t19","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#si-trois，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#si-trois","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:假设"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「si 的三种假设句型」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 条件式与假设三型","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 200 词「如果……会怎样」的推想文。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5009","level":"B1","skill":"writing","prompt":"「如果当年我学了法语，现在就能在巴黎工作」属于？","options":["混合假设","第一型假设","纯现实条件"],"answer":"混合假设","explain":"过去条件配现在结果属于混合假设，需要愈过去时配条件式现在时。","source":"语法 · 假设三型"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#si-trois，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#si-trois","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:假设"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「si 的三种假设句型」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une condition\">une condition</span>（条件）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 条件式与假设三型","type":"review","steps":[{"type":"review","title":"本周回顾：条件式与假设三型","body":"这一周围绕「条件式与假设三型」展开：语法主线是 si 的三种假设句型，词汇主线是 社会与议题。先用 3 句话口头复述本周学了什么，再打开日历页第 35 周清单逐条核对里程碑。","src":"calendar.html#wk-35","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"语法复盘：si 的三种假设句型","body":"从 grammar-b1b2.html#si-trois 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#si-trois","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:假设"}]},{"type":"review","title":"词汇自测：社会与议题","body":"遮住中文看 vocab.html#t19 的 6 个核心词：<span class=\"fr\" data-fr=\"une condition\">une condition</span> <span class=\"fr\" data-fr=\"une hypothèse\">une hypothèse</span> <span class=\"fr\" data-fr=\"un citoyen\">un citoyen</span> <span class=\"fr\" data-fr=\"une politique\">une politique</span> <span class=\"fr\" data-fr=\"dépendre de\">dépendre de</span> <span class=\"fr\" data-fr=\"sinon\">sinon</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t19","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5035","level":"B1","skill":"vocab","prompt":"« une politique » 的意思是？","options":["政策或政治","政治人物","警察"],"answer":"政策或政治","explain":"politique 可指政策，也可指政治；politicien 是政治人物。","source":"词汇 · 政治"},{"id":"q-vocab-b1-5036","level":"B1","skill":"vocab","prompt":"« dépendre de » 的意思是？","options":["取决于","依靠别人","解释"],"answer":"取决于","explain":"dépendre de 表示取决于、依赖于。","source":"词汇 · 高频搭配"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d30","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5018","level":"B1","skill":"listening","prompt":"假设句 « si j'étais riche » 属于哪一型？","options":["第二型","第一型","第三型"],"answer":"第二型","explain":"si 加未完成过去时是第二型假设，主句用条件式现在时。","source":"语法 · 假设三型"},{"id":"q-read-b1-5018","level":"B1","skill":"reading","prompt":"第一型假设的主句可以是什么时态？","options":["现在时或简单将来时","条件式过去时","虚拟式"],"answer":"现在时或简单将来时","explain":"现实条件的主句用现在时（普遍情况）或简单将来时（具体结果）。","source":"语法 · 假设三型"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 si 的三种假设句型 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#si-trois 再核对一次。","src":"grammar-b1b2.html#cond-usage","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5035","level":"B1","skill":"grammar","prompt":"「如果我有时间，我就会去」应说？","options":["Si j'avais le temps, j'irais.","Si j'avais le temps, j'irai.","Si j'aurais le temps, j'irais."],"answer":"Si j'avais le temps, j'irais.","explain":"si 从句用未完成过去时，主句用条件式现在时。","source":"语法 · 假设三型"},{"id":"q-gram-b1-5036","level":"B1","skill":"grammar","prompt":"下列哪句是错误的？","options":["Si tu serais là, ce serait mieux.","Si tu étais là, ce serait mieux.","S'il pleuvait, nous resterions."],"answer":"Si tu serais là, ce serait mieux.","explain":"si 从句里不能用条件式；正确的第二型是 Si tu étais là。","source":"语法 · 假设三型"},{"ref":"bank:grammar:B1:假设"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":36,"level":"B1","theme":"工作与职业规划：面试与职场沟通","days":[{"day":1,"theme":"词汇 · 工作与职业","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：工作与职业","body":"工作与职业（Le travail et les métiers）是这一周要反复见面的主题域。打开 vocab.html#t11，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"une réunion\">une réunion</span>（会议）、<span class=\"fr\" data-fr=\"un collègue\">un collègue</span>（同事）、<span class=\"fr\" data-fr=\"négocier\">négocier</span>（谈判）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t11","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5037","level":"B1","skill":"vocab","prompt":"« négocier » 的意思是？","options":["谈判","否认","通知"],"answer":"谈判","explain":"négocier 是谈判、协商；nier 是否认；notifier 是通知。","source":"词汇 · 职场"},{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"vocab","title":"搭配与辨析：un contrat / un salaire","body":"<span class=\"fr\" data-fr=\"un contrat\">un contrat</span>（合同）与 <span class=\"fr\" data-fr=\"un salaire\">un salaire</span>（工资）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t11","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5038","level":"B1","skill":"vocab","prompt":"« un salaire » 的意思是？","options":["工资","签名","报价"],"answer":"工资","explain":"salaire 是工资；signature 是签名；devis 是报价。","source":"词汇 · 职场"},{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"listen","title":"听音辨词：工作与职业","body":"打开 对话页的 d25、d31 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un accord\">un accord</span>（协议）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d25","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Si vous le permettez, je nuancerais ce point.\">Si vous le permettez, je nuancerais ce point.</span>（如果您允许，我想对这个点做个补充。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：工作与职业 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une réunion\">une réunion</span> <span class=\"fr\" data-fr=\"un collègue\">un collègue</span> <span class=\"fr\" data-fr=\"négocier\">négocier</span> <span class=\"fr\" data-fr=\"un contrat\">un contrat</span> <span class=\"fr\" data-fr=\"un salaire\">un salaire</span> <span class=\"fr\" data-fr=\"un accord\">un accord</span>。说不出来的词立刻回到 vocab.html#t11 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t11","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]}]},{"day":2,"theme":"语法 · 条件式现在时：三大用法","type":"grammar","steps":[{"type":"grammar","title":"语法点：条件式现在时：三大用法","body":"【条件式现在时：三大用法】职场沟通里的礼貌与委婉主要靠条件式（je souhaiterais、si vous le permettez）与情态表达（je nuancerais、disons que）。表达同意、保留与协商时，先认可对方再提出自己的条件，比直接否定更容易达成一致。动词加介词的搭配也要一并核对。 例句：<span class=\"fr\" data-fr=\"Si vous le permettez, je nuancerais ce point.\">Si vous le permettez, je nuancerais ce point.</span>（如果您允许，我想对这个点做个补充。）；<span class=\"fr\" data-fr=\"Je tiens à remercier toute l'équipe.\">Je tiens à remercier toute l'équipe.</span>（我一定要感谢整个团队。）。对照 grammar-b1b2.html#cond-usage 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#cond-usage","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5037","level":"B1","skill":"grammar","prompt":"职场里委婉表达不同意见，最得体的说法是？","options":["Je nuancerais ce point.","Vous avez tort.","C'est faux."],"answer":"Je nuancerais ce point.","explain":"条件式 nuancerais 表示「我想做个补充」，比直接否定更专业。","source":"语法 · 条件式礼貌用法"},{"ref":"bank:grammar:B1:条件式"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#cond-usage 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Si vous le permettez, je nuancerais ce point.\">Si vous le permettez, je nuancerais ce point.</span>（如果您允许，我想对这个点做个补充。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#cond-usage","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5038","level":"B1","skill":"grammar","prompt":"« Je tiens ___ vous remercier. »","options":["à","de","pour"],"answer":"à","explain":"tenir à 加不定式表示一定要、坚持要做某事。","source":"语法 · 动词加介词"},{"ref":"bank:grammar:B1:条件式"}]},{"type":"read","title":"在短文里找条件式现在时：三大用法","body":"在 grammar-b1b2.html#cond-usage 的例句和章末小测里挑 5 句，圈出所有属于「条件式现在时：三大用法」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#cond-usage","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Si vous le permettez, je nuancerais ce point.\">Si vous le permettez, je nuancerais ce point.</span>（如果您允许，我想对这个点做个补充。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，条件式现在时：三大用法 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：动词加介词搭配","body":"今天再回 grammar-b1b2.html#verbes-prepositions 看一遍 动词加介词搭配，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#verbes-prepositions","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:条件式"}]}]},{"day":3,"theme":"精听 · 对话页的 d25、d31 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d25、d31 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d25","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5019","level":"B1","skill":"listening","prompt":"会议中 « On se met d'accord sur ce point ? » 的意思是？","options":["这一点我们达成一致吗","这一点我们改天再谈","这一点谁负责"],"answer":"这一点我们达成一致吗","explain":"se mettre d'accord 是达成一致，这里用疑问语气确认共识。","source":"词汇 · 职场"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段工作会议音频，记录任务分工与决策。","src":"dialogue.html#d25","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une réunion\">une réunion</span>（会议）、<span class=\"fr\" data-fr=\"un collègue\">un collègue</span>（同事）、<span class=\"fr\" data-fr=\"négocier\">négocier</span>（谈判）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t11","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「条件式现在时：三大用法 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d25","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 面试与职场沟通","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：完整模拟面试 10 分钟（自我介绍、经历、优势劣势、提问环节）。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5010","level":"B1","skill":"speaking","prompt":"面试中被问到缺点，最合适的回答是？","options":["说出一个真实缺点并说明改进方式","说自己没有缺点","回避问题"],"answer":"说出一个真实缺点并说明改进方式","explain":"承认一个真实且可改进的缺点，并给出具体改进动作，最有说服力。","source":"口语 · 面试"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d25、d31 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、条件式现在时：三大用法 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d25","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un contrat\">un contrat</span>（合同）、<span class=\"fr\" data-fr=\"un salaire\">un salaire</span>（工资）、<span class=\"fr\" data-fr=\"un accord\">un accord</span>（协议）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t11 再看一遍例句。","src":"vocab.html#t11","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 面试与职场沟通","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读 2 篇 700 词职场话题文章（远程办公、工作生活平衡）。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5019","level":"B1","skill":"reading","prompt":"「工作生活平衡」的法语表达是？","options":["l'équilibre entre vie professionnelle et vie personnelle","le travail équilibre","la vie sans travail"],"answer":"l'équilibre entre vie professionnelle et vie personnelle","explain":"这是职场话题里的高频固定说法。","source":"词汇 · 职场"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une réunion\">une réunion</span>（会议）、<span class=\"fr\" data-fr=\"un collègue\">un collègue</span>（同事）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t11","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#cond-usage，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#cond-usage","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:条件式"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「条件式现在时：三大用法」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 面试与职场沟通","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 250 词动机信 B1 版加一份会议纪要。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5010","level":"B1","skill":"writing","prompt":"会议纪要最合适的一句结构是？","options":["Décision : reporter la réunion à vendredi.","On a parlé de choses.","J'ai dit quelque chose."],"answer":"Décision : reporter la réunion à vendredi.","explain":"纪要要写清决定与责任人，用名词化结构更简洁。","source":"写作 · 会议纪要"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#cond-usage，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#cond-usage","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:条件式"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「条件式现在时：三大用法」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une réunion\">une réunion</span>（会议）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 面试与职场沟通","type":"review","steps":[{"type":"review","title":"本周回顾：工作与职业规划：面试与职场沟通","body":"这一周围绕「工作与职业规划：面试与职场沟通」展开：语法主线是 条件式现在时：三大用法，词汇主线是 工作与职业。先用 3 句话口头复述本周学了什么，再打开日历页第 36 周清单逐条核对里程碑。","src":"calendar.html#wk-36","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"review","title":"语法复盘：条件式现在时：三大用法","body":"从 grammar-b1b2.html#cond-usage 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#cond-usage","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:条件式"}]},{"type":"review","title":"词汇自测：工作与职业","body":"遮住中文看 vocab.html#t11 的 6 个核心词：<span class=\"fr\" data-fr=\"une réunion\">une réunion</span> <span class=\"fr\" data-fr=\"un collègue\">un collègue</span> <span class=\"fr\" data-fr=\"négocier\">négocier</span> <span class=\"fr\" data-fr=\"un contrat\">un contrat</span> <span class=\"fr\" data-fr=\"un salaire\">un salaire</span> <span class=\"fr\" data-fr=\"un accord\">un accord</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t11","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5039","level":"B1","skill":"vocab","prompt":"« un accord » 的意思是？","options":["协议或一致","和弦","准确"],"answer":"协议或一致","explain":"accord 在职场里指协议、一致，也可指和弦。","source":"词汇 · 职场"},{"id":"q-vocab-b1-5040","level":"B1","skill":"vocab","prompt":"« une réunion » 的意思是？","options":["会议","重聚的朋友","联合"],"answer":"会议","explain":"réunion 在职场语境里指会议，也可指重新聚合。","source":"词汇 · 职场"},{"ref":"bank:vocab:A1:工作与职业"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d25","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5020","level":"B1","skill":"listening","prompt":"听到 « si vous le permettez » 时表示？","options":["如果您允许","如果您愿意来","如果您有时间"],"answer":"如果您允许","explain":"permettez 是 permettre 的条件式，用于礼貌地征得同意。","source":"语法 · 条件式礼貌用法"},{"id":"q-read-b1-5020","level":"B1","skill":"reading","prompt":"动机信里表达「我希望能与您面谈」应说？","options":["Je souhaiterais vous rencontrer.","Je veux vous voir.","Venez me voir."],"answer":"Je souhaiterais vous rencontrer.","explain":"正式文书用条件式加完整动词，避免口语化的 vouloir 与命令式。","source":"写作 · 动机信"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 条件式现在时：三大用法 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#cond-usage 再核对一次。","src":"grammar-b1b2.html#verbes-prepositions","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5039","level":"B1","skill":"grammar","prompt":"« Cela dépend ___ votre décision. »","options":["de","à","pour"],"answer":"de","explain":"dépendre de 表示取决于，介词固定用 de。","source":"语法 · 动词加介词"},{"id":"q-gram-b1-5040","level":"B1","skill":"grammar","prompt":"« Je ___ à ce que ce soit possible. »（tenir）","options":["tiens","tienne","tiendrai"],"answer":"tiens","explain":"主句动词 tenir 用直陈式按主语变位为 tiens，从句用虚拟式 soit。","source":"语法 · 虚拟式与主句"},{"ref":"bank:grammar:B1:条件式"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]}];
